    INSERT INTO public.cms_list_items (page, collection_key, locale, order_index, fields, status) VALUES
    ('faq', 'faq_items', 'zh-HK', 0, '{"question":"如何預訂球桌？","answer":"選擇日期、時段及時長，以 Apple Pay 或信用卡即時付款，確認後即獲 QR 碼。全程不需人手協助。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 1, '{"question":"預訂後如何入場？","answer":"付款確認後，你將收到專屬 QR 碼。到場掃描門口感應器，系統自動開門，全程自助。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 2, '{"question":"可以即場取消嗎？","answer":"開始前 2 小時內可免費取消，全額退款。逾時取消將不獲退款。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 3, '{"question":"營業時間是什麼？","answer":"每日 06:00 至 24:00 營業，全年無休，包括公眾假期。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 4, '{"question":"每次最少預訂多少時間？","answer":"最少 1 小時，可選 1、2 或 3 小時。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 5, '{"question":"收費如何計算？","answer":"下午（12pm–6pm）及深夜（12am–6am）每小時 HK$60；晚上（6pm–12am）每小時 HK$80。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 6, '{"question":"什麼是積分制度？","answer":"每消費 HK$1 賺取 1 積分。累積至 500 分升級 Century，享 9 折及積分 1.5 倍；累積至 1,500 分升級 Maximum，享 8 折及免費教練時段。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 7, '{"question":"場地內有什麼設備？","answer":"專業桌球枱、頂級燈光設備、冷氣、免費 Wi-Fi，以及自助飲品區。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 8, '{"question":"可以帶朋友一起來嗎？","answer":"可以，每個時段可容納多人，費用按時段計算，無需額外收費。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-HK', 9, '{"question":"如有問題如何聯絡？","answer":"可透過 WhatsApp 聯絡我們，或發送電郵至 hello@space8.com.hk，我們將盡快回覆。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 0, '{"question":"如何预订球桌？","answer":"选择日期、时段及时长，以 Apple Pay 或信用卡即时付款，确认后即获 QR 码。全程不需人工协助。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 1, '{"question":"预订后如何入场？","answer":"付款确认后，你将收到专属 QR 码。到场扫描门口感应器，系统自动开门，全程自助。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 2, '{"question":"可以取消预订吗？","answer":"开始前 2 小时内可免费取消，全额退款。逾时取消将不获退款。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 3, '{"question":"营业时间是什么？","answer":"每日 06:00 至 24:00 营业，全年无休，包括公众假期。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 4, '{"question":"每次最少预订多少时间？","answer":"最少 1 小时，可选 1、2 或 3 小时。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 5, '{"question":"收费如何计算？","answer":"下午（12pm–6pm）及深夜（12am–6am）每小时 HK$60；晚上（6pm–12am）每小时 HK$80。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 6, '{"question":"什么是积分制度？","answer":"每消费 HK$1 赚取 1 积分。累积至 500 分升级 Century，享 9 折及积分 1.5 倍；累积至 1,500 分升级 Maximum，享 8 折及免费教练时段。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 7, '{"question":"场地内有什么设备？","answer":"专业台球台、顶级灯光设备、冷气、免费 Wi-Fi，以及自助饮品区。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 8, '{"question":"可以带朋友一起来吗？","answer":"可以，每个时段可容纳多人，费用按时段计算，无需额外收费。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'zh-CN', 9, '{"question":"如有问题如何联系？","answer":"可透过 WhatsApp 联系我们，或发送电邮至 hello@space8.com.hk，我们将尽快回复。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 0, '{"question":"How do I book a table?","answer":"Select a date, time slot, and duration, then pay instantly with Apple Pay or a credit card. You''ll receive a QR code immediately. No staff assistance required."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 1, '{"question":"How do I enter after booking?","answer":"After payment, you''ll receive a unique QR code. Scan the door sensor on arrival and the system unlocks automatically — fully self-service."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 2, '{"question":"Can I cancel my booking?","answer":"You can cancel for free up to 2 hours before your session starts and receive a full refund. Cancellations after that are non-refundable."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 3, '{"question":"What are the opening hours?","answer":"Space8 is open daily from 06:00 to 24:00, year-round, including public holidays."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 4, '{"question":"What is the minimum booking duration?","answer":"The minimum is 1 hour. You can book 1, 2, or 3 hours."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 5, '{"question":"How is pricing calculated?","answer":"Afternoon (12pm–6pm) and late night (12am–6am) are HK$60/hr. Evening (6pm–12am) is HK$80/hr."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 6, '{"question":"How does the points system work?","answer":"Earn 1 point per HK$1 spent. Reach 500 points for Century tier (10% off, 1.5× points). Reach 1,500 for Maximum tier (20% off, free coaching)."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 7, '{"question":"What facilities are available?","answer":"Professional snooker tables, premium lighting, air conditioning, free Wi-Fi, and a self-serve drinks area."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 8, '{"question":"Can I bring friends?","answer":"Yes, each session can accommodate multiple players. The session fee covers everyone — no extra charge per person."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'en', 9, '{"question":"How can I contact you?","answer":"Reach us via WhatsApp or email hello@space8.com.hk — we''ll get back to you promptly."}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 0, '{"question":"テーブルの予約方法は？","answer":"日付・時間帯・プレイ時間を選択し、Apple Payまたはクレジットカードで即時決済。QRコードがすぐに届きます。スタッフ対応は不要です。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 1, '{"question":"予約後の入場方法は？","answer":"支払い確認後、専用QRコードが届きます。ドアセンサーをスキャンするだけで自動解錠、完全セルフサービスです。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 2, '{"question":"キャンセルはできますか？","answer":"セッション開始2時間前までは無料でキャンセル、全額返金されます。それ以降のキャンセルは返金対象外です。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 3, '{"question":"営業時間は？","answer":"Space8 は毎日06:00から24:00まで、年中無休で営業しています（祝日含む）。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 4, '{"question":"最低予約時間は？","answer":"最低1時間から。1・2・3時間でお選びいただけます。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 5, '{"question":"料金の計算方法は？","answer":"午後（12pm–6pm）と深夜（12am–6am）はHK$60/時間。夜（6pm–12am）はHK$80/時間です。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 6, '{"question":"ポイント制度について教えてください。","answer":"HK$1ごとに1ポイント獲得。500ポイントでCentury（10%割引・1.5倍ポイント）、1,500ポイントでMaximum（20%割引・無料コーチング）にアップグレードされます。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 7, '{"question":"施設内の設備は？","answer":"プロ仕様のスヌーカーテーブル、高品質照明、エアコン、無料Wi-Fi、セルフサービスドリンクコーナーをご用意しています。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 8, '{"question":"友人を連れて来られますか？","answer":"はい、各セッションに複数名が参加できます。料金はセッション単位で、追加費用はかかりません。"}'::jsonb, 'published'),
    ('faq', 'faq_items', 'ja', 9, '{"question":"お問い合わせ方法は？","answer":"WhatsAppまたはhello@space8.com.hkまでご連絡ください。できる限り早くお返事いたします。"}'::jsonb, 'published');
    INSERT INTO public.cms_list_items (page, collection_key, locale, order_index, fields, status) VALUES
    ('legal', 'terms_sections', 'zh-HK', 0, '{"title":"服務說明","body":"Space8 由 FORM 營運，提供香港首間自助英式桌球預訂服務，營業時間為每日 06:00 至 24:00。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 1, '{"title":"預訂條款","body":"每位用戶最多可持有 2 個有效預訂，每張枱最多 2 人，名額先到先得。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 2, '{"title":"入場規則","body":"入場須出示專屬 QR 碼。遲到逾 15 分鐘視為自動放棄，QR 碼不得轉讓他人。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 3, '{"title":"場地規則","body":"場內禁止吸煙、賭博及攜帶外來食物。請愛護設備，違規者預訂將被取消且不獲退款。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 4, '{"title":"付款條款","body":"所有費用以港幣 (HKD) 計算，接受信用卡、Apple Pay、Google Pay、Alipay 及 WeChat Pay。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 5, '{"title":"逾時條款","body":"逾時每 15 分鐘收費 HK$50，將從已登記的信用卡自動扣除。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 6, '{"title":"積分計劃","body":"每消費 HK$10 可獲 1 積分。積分不可兌換現金，有效期為 24 個月。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 7, '{"title":"免責聲明","body":"Space8 不對任何財物損失或人身傷害承擔責任。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-HK', 8, '{"title":"適用法律","body":"本條款受香港特別行政區法律管轄並據此詮釋。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 0, '{"title":"服务说明","body":"Space8 由 FORM 运营，提供香港首家自助英式台球预订服务，营业时间为每日 06:00 至 24:00。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 1, '{"title":"预订条款","body":"每位用户最多可持有 2 个有效预订，每张台最多 2 人，名额先到先得。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 2, '{"title":"入场规则","body":"入场须出示专属二维码。迟到超过 15 分钟视为自动放弃，二维码不得转让他人。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 3, '{"title":"场地规则","body":"场内禁止吸烟、赌博及携带外来食物。请爱护设备，违规者预订将被取消且不予退款。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 4, '{"title":"付款条款","body":"所有费用以港币 (HKD) 计算，接受信用卡、Apple Pay、Google Pay、支付宝及微信支付。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 5, '{"title":"超时条款","body":"超时每 15 分钟收费 HK$50，将从已登记的信用卡自动扣除。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 6, '{"title":"积分计划","body":"每消费 HK$10 可获 1 积分。积分不可兑换现金，有效期为 24 个月。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 7, '{"title":"免责声明","body":"Space8 不对任何财物损失或人身伤害承担责任。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'zh-CN', 8, '{"title":"适用法律","body":"本条款受香港特别行政区法律管辖并据此解释。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 0, '{"title":"Service Description","body":"Space8 is operated by FORM, offering Hong Kong’s first self-service English snooker booking platform, open daily from 06:00 to 24:00."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 1, '{"title":"Booking Terms","body":"Each user may hold up to 2 active bookings. Each table seats up to 2 players, allocated first-come, first-served."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 2, '{"title":"Entry Rules","body":"A valid QR code is required for entry. Arriving more than 15 minutes late forfeits the booking. QR codes are non-transferable."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 3, '{"title":"House Rules","body":"No smoking, gambling, or outside food. Please respect the equipment — violations result in cancellation without refund."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 4, '{"title":"Payment Terms","body":"All fees are in HKD. We accept credit cards, Apple Pay, Google Pay, Alipay, and WeChat Pay."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 5, '{"title":"Overtime","body":"Overtime is charged at HK$50 per 15 minutes, deducted automatically from your registered card."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 6, '{"title":"Points Programme","body":"Earn 1 point per HK$10 spent. Points hold no cash value and expire after 24 months."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 7, '{"title":"Disclaimer","body":"Space8 is not liable for any loss of property or personal injury."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'en', 8, '{"title":"Governing Law","body":"These terms are governed by and construed under the laws of the Hong Kong SAR."}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 0, '{"title":"サービス説明","body":"Space8 は FORM が運営する、香港初のセルフサービス・スヌーカー予約プラットフォームで、毎日06:00から24:00まで営業しています。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 1, '{"title":"予約規約","body":"各ユーザーは有効な予約を最大2件まで保持できます。各テーブルは最大2名、先着順です。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 2, '{"title":"入場ルール","body":"入場には専用QRコードが必要です。15分以上の遅刻は放棄とみなされ、QRコードは譲渡できません。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 3, '{"title":"施設ルール","body":"館内は禁煙・賭博・外部飲食物の持ち込み禁止です。設備を大切にし、違反した場合は返金なしでキャンセルとなります。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 4, '{"title":"支払い規約","body":"料金はすべて HKD です。クレジットカード、Apple Pay、Google Pay、Alipay、WeChat Pay に対応しています。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 5, '{"title":"超過料金","body":"超過料金は15分ごとに HK$50 で、登録済みカードから自動的に引き落とされます。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 6, '{"title":"ポイントプログラム","body":"HK$10 ごとに1ポイント獲得。ポイントに換金性はなく、有効期限は24か月です。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 7, '{"title":"免責事項","body":"Space8 は財物の損失や人身傷害について一切の責任を負いません。"}'::jsonb, 'published'),
    ('legal', 'terms_sections', 'ja', 8, '{"title":"準拠法","body":"本規約は香港特別行政区の法律に準拠し、解釈されます。"}'::jsonb, 'published');
    INSERT INTO public.cms_list_items (page, collection_key, locale, order_index, fields, status) VALUES
    ('legal', 'privacy_sections', 'zh-HK', 0, '{"title":"收集資料","body":"我們收集姓名、電郵、電話、付款資料、預訂記錄及 CCTV 影像。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-HK', 1, '{"title":"使用目的","body":"用於處理預訂、發送通知、管理積分及改善服務質素。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-HK', 2, '{"title":"第三方服務","body":"我們使用 Stripe、Google、Supabase、Resend 及 WhatsApp 等第三方服務。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-HK', 3, '{"title":"資料保留","body":"CCTV 影像最多保留 31 日；付款資料由 Stripe 處理及保存。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-HK', 4, '{"title":"您的權利","body":"您有權查閱、更正或刪除個人資料，請電郵 info.formhk@gmail.com 聯絡我們。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-HK', 5, '{"title":"Cookie","body":"繼續使用本網站即表示您同意我們使用 Cookie。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-HK', 6, '{"title":"聯絡我們","body":"info.formhk@gmail.com／+852 6427 4620"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 0, '{"title":"收集信息","body":"我们收集姓名、邮箱、电话、付款信息、预订记录及 CCTV 影像。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 1, '{"title":"使用目的","body":"用于处理预订、发送通知、管理积分及改善服务质量。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 2, '{"title":"第三方服务","body":"我们使用 Stripe、Google、Supabase、Resend 及 WhatsApp 等第三方服务。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 3, '{"title":"数据保留","body":"CCTV 影像最多保留 31 日；付款信息由 Stripe 处理及保存。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 4, '{"title":"您的权利","body":"您有权查阅、更正或删除个人信息，请发送邮件至 info.formhk@gmail.com 联系我们。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 5, '{"title":"Cookie","body":"继续使用本网站即表示您同意我们使用 Cookie。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'zh-CN', 6, '{"title":"联系我们","body":"info.formhk@gmail.com／+852 6427 4620"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 0, '{"title":"Data We Collect","body":"We collect your name, email, phone, payment details, booking history, and CCTV footage."}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 1, '{"title":"How We Use It","body":"To process bookings, send notifications, manage points, and improve our service."}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 2, '{"title":"Third-Party Services","body":"We use Stripe, Google, Supabase, Resend, and WhatsApp."}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 3, '{"title":"Data Retention","body":"CCTV footage is kept for up to 31 days. Payment data is handled and stored by Stripe."}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 4, '{"title":"Your Rights","body":"You may access, correct, or delete your data by contacting info.formhk@gmail.com."}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 5, '{"title":"Cookies","body":"By continuing to use this site, you consent to our use of cookies."}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'en', 6, '{"title":"Contact","body":"info.formhk@gmail.com / +852 6427 4620"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 0, '{"title":"収集する情報","body":"氏名、メール、電話番号、支払い情報、予約履歴、CCTV映像を収集します。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 1, '{"title":"利用目的","body":"予約処理、通知送信、ポイント管理、サービス改善のために利用します。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 2, '{"title":"第三者サービス","body":"Stripe、Google、Supabase、Resend、WhatsApp を利用しています。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 3, '{"title":"データ保持","body":"CCTV映像は最大31日間保持します。支払い情報は Stripe が処理・保管します。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 4, '{"title":"お客様の権利","body":"info.formhk@gmail.com までご連絡いただければ、情報の閲覧・訂正・削除が可能です。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 5, '{"title":"Cookie","body":"本サイトの利用を継続することで、Cookie の使用に同意したものとみなされます。"}'::jsonb, 'published'),
    ('legal', 'privacy_sections', 'ja', 6, '{"title":"お問い合わせ","body":"info.formhk@gmail.com／+852 6427 4620"}'::jsonb, 'published');
